
from fractions import Fraction
import itertools
import random
import re

# ========== 五度圈 ==========
CIRCLE = ["C", "G", "D", "A", "E", "B", "F#", "Db", "Ab", "Eb", "Bb", "F"]
N = len(CIRCLE)

NAME_TO_PITCH = {
    "C": 0, "B#": 0,
    "C#": 1, "Db": 1,
    "D": 2,
    "D#": 3, "Eb": 3,
    "E": 4, "Fb": 4,
    "F": 5, "E#": 5,
    "F#": 6, "Gb": 6,
    "G": 7,
    "G#": 8, "Ab": 8,
    "A": 9,
    "A#": 10, "Bb": 10,
    "B": 11, "Cb": 11,
}

PITCH_TO_NAME = {
    0: "C", 1: "Db", 2: "D", 3: "Eb", 4: "E", 5: "F",
    6: "F#", 7: "G", 8: "Ab", 9: "A", 10: "Bb", 11: "B",
}



# ========== 基础计算 ==========
def fifth_span_detail(pitch_classes):
    """
    在五度圈上枚举起点与方向，取第一次覆盖全部和弦音时步数最短的那次遍历。
    返回 (起点索引, 终点索引, 方向, 纯五度跨度, 遍历覆盖的索引列表)
    方向: +1 升序, -1 降序
    """
    notes = {PITCH_TO_NAME[p] for p in pitch_classes}
    notes = {n for n in notes if n in CIRCLE}
    if not notes:
        return None
    positions = {CIRCLE.index(n) for n in notes}
    best = None
    for start in positions:
        for direction in (1, -1):
            covered = []
            distance = 0
            pos = start
            for _ in range(N):
                covered.append(pos)
                if positions.issubset(set(covered)):
                    if best is None or distance < best[3]:
                        best = (start, pos, direction, distance, covered[:])
                    break
                pos = (pos + direction) % N
                distance += 1
    return best


def interval_stats(pitch_classes):
    """返回 (大二度个数, 半音程个数)。

    两者都按音程级统计：小二度(1)和大七度(11)都算，大二度(2)和小七度(10)都算。
    只数 iv==2 会让同一个结构换个八度摆法就少算一个大二度，等级跟着移调漂。
    """
    pitches = sorted(pitch_classes)
    major2 = 0
    semitone = 0
    for i in range(len(pitches)):
        for j in range(i + 1, len(pitches)):
            iv = (pitches[j] - pitches[i]) % 12
            if iv in (2, 10):
                major2 += 1
            if iv in (1, 11):
                semitone += 1
    return major2, semitone


def has_major_or_minor_triad(pitch_classes):
    pitches = sorted(pitch_classes)
    n = len(pitches)
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if i == j or j == k or i == k:
                    continue
                a, b, c = pitches[i], pitches[j], pitches[k]
                if (b - a) % 12 == 4 and (c - a) % 12 == 7:
                    return True
                if (b - a) % 12 == 3 and (c - a) % 12 == 7:
                    return True
    return False


def consecutive_semitone_stats(pitch_classes):
    """统计半音程游程，按十二音环首尾相接。

    B-C-Db 这类跨八度接缝的连续半音算一组，与 interval_stats 的音程级口径一致。
    返回 (最长游程, 长度≥2的游程个数)。
    """
    pitches = sorted(pitch_classes)
    intervals = [(pitches[i + 1] - pitches[i]) % 12
                 for i in range(len(pitches) - 1)]
    intervals.append((pitches[0] - pitches[-1]) % 12)

    break_at = next((i for i, iv in enumerate(intervals) if iv != 1), None)
    if break_at is None:
        # 整个环都是半音阶
        return len(intervals), 0
    intervals = intervals[break_at + 1:] + intervals[:break_at + 1]

    max_run = 0
    cur = 0
    run_count = 0
    for iv in intervals:
        if iv == 1:
            cur += 1
            max_run = max(max_run, cur)
        else:
            if cur >= 2:
                run_count += 1
            cur = 0
    return max_run, run_count


# ========== 常规/复杂和弦 ==========
MAJOR_SCALE = {0, 2, 4, 5, 7, 9, 11}
NATURAL_MINOR = {0, 2, 3, 5, 7, 8, 10}
HARMONIC_MINOR = {0, 2, 3, 5, 7, 8, 11}
MELODIC_MINOR = {0, 2, 3, 5, 7, 9, 11}
HARMONIC_MAJOR = {0, 2, 4, 5, 7, 8, 11}
SCALES = [MAJOR_SCALE, NATURAL_MINOR, HARMONIC_MINOR, MELODIC_MINOR, HARMONIC_MAJOR]


def is_regular_chord(pitch_classes):
    for root in range(12):
        for scale in SCALES:
            transposed = {(p + root) % 12 for p in scale}
            if pitch_classes.issubset(transposed):
                return True
    return False


# ========== 张力等级判断 ==========
def get_tension_level(pitch_classes):
    detail = fifth_span_detail(pitch_classes)
    if detail is None:
        return None, None, None, None
    span = detail[3]

    major2, semitone = interval_stats(pitch_classes)
    has_triad = has_major_or_minor_triad(pitch_classes)
    is_regular = is_regular_chord(pitch_classes)
    max_run, run_count = consecutive_semitone_stats(pitch_classes)

    # 逐条严格对应规则原文，任何一条都不满足时保持 None（无法归类）
    level = None

    if semitone == 0:
        if 2 <= span <= 4:
            if major2 <= 1:
                level = "1a" if has_triad else "1b"
            elif major2 in (2, 3):
                level = "1c"
        elif span == 6:
            if major2 <= 1:
                level = "2a" if has_triad else "2b"
            elif major2 in (2, 3):
                level = "2c"
        elif 7 <= span <= 11:
            if span == 8 and major2 <= 1:
                level = "3a"
            elif span == 8 and major2 == 2:
                level = "3b"
            elif major2 > 2 or span > 8:
                level = "3c"

    elif semitone == 1:
        if span == 5:
            if major2 > 2 or not has_triad:
                level = "4c"
            elif major2 == 2:
                level = "4b"
            else:
                level = "4a"
        elif span == 6:
            if major2 > 2 or not has_triad:
                level = "5c"
            elif major2 == 2:
                level = "5b"
            elif major2 <= 1:
                level = "5a"
        elif 7 <= span <= 11:
            if major2 > 2 or not has_triad:
                level = "6c"
            elif major2 == 0:
                level = "6a"
            elif major2 in (1, 2):
                level = "6b"

    elif semitone == 2:
        if span == 6:
            if major2 > 1 or not has_triad:
                level = "7b"
            elif major2 <= 1:
                level = "7a"
        elif 7 <= span <= 11:
            if is_regular:
                if major2 <= 2 and has_triad:
                    level = "8a"
                elif major2 > 2 or not has_triad:
                    level = "8b"
            else:
                if major2 <= 3 and has_triad:
                    level = "8c"
                elif major2 > 3 or not has_triad:
                    level = "8d"

    elif semitone == 3:
        if 7 <= span <= 11:
            if max_run >= 3:
                level = "9c"
            elif max_run == 2:
                level = "9b"
            elif max_run <= 1:
                level = "9a"

    elif semitone >= 4:
        if 7 <= span <= 11:
            if max_run >= 4:
                level = "10d"
            elif max_run == 3:
                level = "10c"
            elif max_run == 2 and run_count >= 2:
                level = "10b"
            else:
                # 原著 X 行漏格：只有一组连续两个（或半音全孤立）。用户决定补的这格现名 10a。
                level = "10a"

    return level, span, (major2, semitone), (max_run, run_count)
import math

# ========== 张力等级 → 正序序号 ==========
LEVEL_ORDER = []
for major in range(1, 10):
    if major == 7:
        LEVEL_ORDER.extend([f"{major}a", f"{major}b"])
    elif major == 8:
        LEVEL_ORDER.extend([f"{major}a", f"{major}b", f"{major}c", f"{major}d"])
    else:
        LEVEL_ORDER.extend([f"{major}a", f"{major}b", f"{major}c"])
# 10 组四个子级：位置沿用改名前的老次序，半径比例一个都不动，只换名字
#   老10a(游程==2多组)→10b  老10b(游程==3)→10c  老10c(游程>=4)→10d  老10d(游程<=2单组)→10a
LEVEL_ORDER.extend(["10b", "10c", "10d", "10a"])

LEVEL_COUNT = len(LEVEL_ORDER)

def level_to_radius_ratio(level):
    """
    张力等级 → 半径比例（0~1）。
    正序序号 1~LEVEL_COUNT，倒序位置 = (LEVEL_COUNT - 正序序号) / LEVEL_COUNT。
    """
    if level not in LEVEL_ORDER:
        return None
    idx = LEVEL_ORDER.index(level) + 1   # 正序序号
    return (LEVEL_COUNT - idx) / LEVEL_COUNT


def static_tension(level):
    """静态张力：和弦点到圆心的距离取反（10 − 10×半径比例）。
    越紧张的点越靠近圆心，这个值越大；等级映射不出半径时返回 None。"""
    ratio = level_to_radius_ratio(level)
    if ratio is None:
        return None
    return 10 * (1 - ratio)


def fold_to_half_circle(offset):
    """把五度圈上的格数差折到 -6~+6，两个方向谁近就记谁。"""
    return (offset + 6) % 12 - 6


def relative_offsets(pitch_classes, bass_index):
    """各音相对低音在五度圈上的格数偏移，折到 -6~+6（沿近的一边数）。

    正好落在低音对面（第 6 格）的音没有"近的一边"，一律折成 -6 会让
    C-D-E-F# 这类整体偏升号侧的和弦凭空抵消成 0，所以它的符号跟着其余音的重心走。
    其余音重心恰好为 0 时两边完全对称，无从定号，返回的第二个值为 True，交给调用方判中性。
    """
    raw = [(CIRCLE.index(PITCH_TO_NAME[p]) - bass_index) % 12 for p in pitch_classes]
    offsets = [fold_to_half_circle(o) for o in raw]
    if -6 not in offsets:
        return offsets, False
    rest = sum(o for o in offsets if o != -6)
    if rest == 0:
        return offsets, True
    if rest > 0:
        offsets = [6 if o == -6 else o for o in offsets]
    return offsets, False


def point_to_segment_distance(px, py, ax, ay, bx, by):
    """
    点 P(px,py) 到线段 AB 的最短距离。
    A 是圆心 (0,0)，B 是半径端点 (R*cos, R*sin)。
    """
    dx = bx - ax
    dy = by - ay
    if dx == 0 and dy == 0:
        # 线段退化成点
        return math.hypot(px - ax, py - ay)
    # 计算投影参数 t
    t = ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy)
    t = max(0, min(1, t))  # 限制在线段内
    # 投影点
    proj_x = ax + t * dx
    proj_y = ay + t * dy
    return math.hypot(px - proj_x, py - proj_y)
# ========== 温度计算 ==========
def get_temperature(pitch_classes, level, bass_pc):
    """
    低音 bass_pc 是圆上那根针的方向（取输入的第一个音）。
    和弦方向 = 各音相对低音的格数偏移求平均，正为升序侧、负为降序侧。
    张力等级决定和弦方向上的点到圆心有多近，该点到低音针这根线段的最短距离即温度。
    方向重合时无温度，判"平衡"——含偏移均值为 0（重心与低音同向）与半径比例 0
    （和弦点落在圆心、也在低音针上）两种；夹角呈 180°（和弦点压在低音正对面）
    无从定号，以及对径音符号无从定号（其余音重心恰为 0）时，都判"中性"。
    """
    bass_index = CIRCLE.index(PITCH_TO_NAME[bass_pc])
    offsets, is_tie = relative_offsets(pitch_classes, bass_index)
    total_offset = sum(offsets)

    ratio = level_to_radius_ratio(level)
    if ratio is None:
        return None, None

    R = 10
    low_angle = bass_index * 30
    mean_offset = total_offset / len(offsets)
    chord_angle = low_angle + mean_offset * 30

    low_rad = math.radians(low_angle)
    chord_rad = math.radians(chord_angle)
    if is_tie:
        return 0.0, "中性"
    if mean_offset == 0 or ratio == 0:
        # 方向重合：重心与低音同向，或和弦点落在圆心（也在低音针上）
        return 0.0, "平衡"
    if abs(mean_offset) == 6:
        # 夹角 180°：和弦点压在低音正对面，暖冷无从定号
        return 0.0, "中性"
    dist = point_to_segment_distance(
        R * ratio * math.cos(chord_rad), R * ratio * math.sin(chord_rad),
        0, 0,
        R * math.cos(low_rad), R * math.sin(low_rad),
    )
    return (dist, "暖") if total_offset > 0 else (-dist, "冷")


# ========== 和声进行的动态属性 ==========
def chord_point(pitch_classes, level, bass_pc):
    """和弦点在圆上的位置：方向 = 低音方向 + 平均偏移 × 30°，半径 = 等级半径比例 × 10。
    返回 (x, y, 方向弧度)；等级映射不出半径时返回 None。"""
    ratio = level_to_radius_ratio(level)
    if ratio is None:
        return None
    bass_index = CIRCLE.index(PITCH_TO_NAME[bass_pc])
    offsets, _ = relative_offsets(pitch_classes, bass_index)
    angle = math.radians(bass_index * 30 + sum(offsets) / len(offsets) * 30)
    return 10 * ratio * math.cos(angle), 10 * ratio * math.sin(angle), angle


def dynamic_tension(point_a, point_b):
    """动态张力：两个和弦点之间的最短距离。"""
    return math.hypot(point_b[0] - point_a[0], point_b[1] - point_a[1])


def chord_direction(pitch_classes, bass_pc):
    """和弦方向（低音格数 + 平均偏移），以 30° 为一格。

    用分数精确保留，才能把"方向相同（差 0 格）"与"正对面（差 6 格）"
    这两种零值情形做成严格的等于比较，不被浮点误差搅出 -0.000。"""
    bass_index = CIRCLE.index(PITCH_TO_NAME[bass_pc])
    offsets, is_tie = relative_offsets(pitch_classes, bass_index)
    return Fraction(bass_index) + Fraction(sum(offsets), len(offsets)), is_tie


def dynamic_temperature(point_a, point_b, direction_a, direction_b, tie_a, tie_b):
    """动态温度：以和弦1的张力点定一个新圆——圆心到和弦1的张力点（和弦1的点）
    的距离就是新圆半径，恒等于 10 − 和弦1的静态张力（= r₁）；把和弦2的张力点
    按"新圆半径 ÷ 10"的比例缩入新圆，量它到"和弦1方向所在直线"的垂直距离，
    带冷暖。该距离 = r₁ × r₂ × |sinΔ| ÷ 10（r₂ = 和弦2的张力点到圆心距离，
    Δ = 两方向夹角；÷ 10 归一化，能对齐外部对照工具"和弦调试"的"空间温度变化"）。

    冷暖按"从和弦1方向到和弦2方向的最短弧"走哪边定：走 C→G→D…（升五度，
    即五度圈标准画法的顺时针方向）那侧为暖，走 C→F→Bb…（降五度）那侧为冷。
    方向重合（差 0 格）判"平衡"，正对面（差 6 格）判"中性"；任一方含无从
    定号的对径音（is_tie）时方向本身无从谈起，也判"中性"；任一方和弦点落在
    圆心（半径比例 0）时距离恒为 0，判"平衡"。
    """
    if tie_a or tie_b:
        return 0.0, "中性"
    if (point_a[0] == 0 and point_a[1] == 0) or (point_b[0] == 0 and point_b[1] == 0):
        # 任一方和弦点落在圆心（半径比例 0）：无温度可言
        return 0.0, "平衡"
    steps = (direction_b - direction_a) % 12
    if steps == 0:
        return 0.0, "平衡"
    if steps == 6:
        return 0.0, "中性"
    _, _, angle_a = point_a
    _, _, angle_b = point_b
    # 新圆半径 = 圆心到和弦1的张力点（和弦1的点）的距离，恒等于 10 − 和弦1的静态张力
    new_radius = math.hypot(point_a[0], point_a[1])
    # 和弦2的张力点按"新圆半径 ÷ 10"的比例缩入新圆，再量它到和弦1方向直线的垂距
    scaled_radius = math.hypot(point_b[0], point_b[1]) * new_radius / 10
    dist = scaled_radius * abs(math.sin(angle_a - angle_b))
    return (dist, "暖") if steps < 6 else (-dist, "冷")


# ========== 输入解析 ==========
def is_likely_command_line(text):
    """判断输入是否像命令行（VS Code 运行回显）"""
    markers = [".py", "python.exe", "C:\\", "D:\\", "/python", "d:/", "c:/"]
    lower = text.lower()
    return any(m.lower() in lower for m in markers)


def normalize_token(token):
    """
    把用户输入的音名规范化成 NAME_TO_PITCH 里的写法。
    支持：
      C, c, C#, c#, Db, db
      jD  → Db
      jE  → Eb
      jA  → Ab
      jB  → Bb
      jC  → Cb
      jF  → Fb
      #B  → B#
      #E  → E#
      bD  → Db
      bE  → Eb
      C## → 重升，等音 D
      Djj → 重降，等音 C
    """
    token = token.strip()
    if not token:
        return None

    # 去掉八度数字
    while token and token[-1].isdigit():
        token = token[:-1]
    if not token:
        return None

    # ---- 处理重升 ## 和重降 jj ----
    # C## → 重升，等音 D
    # Djj → 重降，等音 C
    if token.endswith("##") or token.endswith("jj"):
        if token.endswith("##"):
            note_part = token[:-2]
            accidental = "##"
        else:
            note_part = token[:-2]
            accidental = "jj"

        if note_part:
            note = note_part[0].upper() + note_part[1:].lower() if len(note_part) > 1 else note_part.upper()
            if note in NAME_TO_PITCH:
                base = NAME_TO_PITCH[note]
                offset = 2 if accidental == "##" else -2
                pitch = (base + offset) % 12
                # 用等音的标准名返回
                return PITCH_TO_NAME[pitch]

    # ---- 升降号在前的写法 ----
    # #B → B#, #E → E#, bD → Db, bE → Eb
    if token[0] in ("#", "b", "B"):
        accidental = token[0]
        if accidental == "B":
            accidental = "b"
        note = token[1:]
        if note:
            note = note[0].upper() + note[1:].lower() if len(note) > 1 else note.upper()
            if accidental == "#":
                candidate = note + "#"
            else:
                candidate = note + "b"
            if candidate in NAME_TO_PITCH:
                return candidate

    # ---- j 前缀降号：jD → Db ----
    first = token[0].upper()
    rest = token[1:]

    if first == "J" and rest:
        note = rest[0].upper() + rest[1:].lower() if len(rest) > 1 else rest.upper()
        candidate = note + "b"
        if candidate in NAME_TO_PITCH:
            return candidate
        return None

    # ---- 正常情况：C, C#, Db ----
    name = first + rest
    if len(name) >= 2 and name[1] == "B":
        name = name[0] + "b"
    if name in NAME_TO_PITCH:
        return name

    # 等音转换
    ENHARMONIC_MAP = {
        "C#": "Db", "Db": "C#",
        "D#": "Eb", "Eb": "D#",
        "F#": "Gb", "Gb": "F#",
        "G#": "Ab", "Ab": "G#",
        "A#": "Bb", "Bb": "A#",
    }
    if name in ENHARMONIC_MAP and ENHARMONIC_MAP[name] in NAME_TO_PITCH:
        return ENHARMONIC_MAP[name]

    return None


def parse_input(text):
    """解析一行输入，返回 (pitch_classes, names, errors)"""
    text = text.replace(",", " ").replace("，", " ")
    tokens = text.split()

    pitch_classes = set()
    names = []
    errors = []

    for token in tokens:
        name = normalize_token(token)
        if name is None:
            errors.append(token)
            continue
        pitch_classes.add(NAME_TO_PITCH[name])
        names.append(name)

    return pitch_classes, names, errors


# ========== 格式化输出 ==========
def format_result(names, pitch_classes, level, span, major2, semitone, max_run, run_count):
    lines = []
    lines.append(f"  输入音名：{names}")
    lines.append(f"  音高类（去重后）：{sorted(pitch_classes)}")
    lines.append(f"  纯五度跨度：{span}")
    lines.append(f"  大二度数量：{major2}")
    lines.append(f"  半音程数量（小二度+大七度）：{semitone}")
    lines.append(f"  最大连续半音程游程：{max_run}")
    lines.append(f"  连续半音程游程个数：{run_count}")

    bass_pc = NAME_TO_PITCH[names[0]]
    lines.append(f"  低音（取输入首音）：{names[0]}")

    temp, warm = get_temperature(pitch_classes, level, bass_pc)
    if temp is not None:
        lines.append(f"  和弦温度：{temp:+.3f}  ({warm})")
    else:
        lines.append(f"  和弦温度：无法计算")

    st = static_tension(level)
    if st is not None:
        lines.append(f"  静态张力：{st:.3f}")
    else:
        lines.append(f"  静态张力：无法计算")

    if level:
        lines.append(f"  ★ 张力等级：{level}")
    else:
        lines.append(f"  ★ 无法归类（跨度不在规则范围，或规则未覆盖）")
    return "\n".join(lines)


# ========== 单次查询 ==========
def query_single(text):
    if "/" in text or "／" in text:
        query_progression(text)
        return
    pitch_classes, names, errors = parse_input(text)
    if errors:
        print(f"  警告：无法识别的音名 {errors}")
    if len(pitch_classes) < 2:
        print("  至少需要两个不同的音。")
        return
    level, span, (major2, semitone), (max_run, run_count) = get_tension_level(pitch_classes)
    print("-" * 60)
    print(format_result(names, pitch_classes, level, span, major2, semitone, max_run, run_count))


# ========== 和声进行 ==========
def query_progression(text):
    """两个和弦用 / 隔开。动态张力 = 两个和弦点之间的最短距离；
    动态温度 = 两个和弦点到圆心的距离相乘再乘方向夹角正弦、除以 10，带冷暖。"""
    parts = [p.strip() for p in text.replace("／", "/").split("/")]
    if len(parts) > 2:
        print(f"  目前最多支持两个和弦（收到 {len(parts)} 个）。")
        return
    if len(parts) < 2 or not all(parts):
        print("  和声进行格式：两个和弦用 / 隔开，例如：C E G / D F A")
        return

    chords = []
    for part in parts:
        pitch_classes, names, errors = parse_input(part)
        if errors:
            print(f"  警告：无法识别的音名 {errors}")
            return
        if len(pitch_classes) < 2:
            print(f"  “{part}”至少需要两个不同的音。")
            return
        level, span, (major2, semitone), (max_run, run_count) = get_tension_level(pitch_classes)
        point = chord_point(pitch_classes, level, NAME_TO_PITCH[names[0]])
        chords.append((names, pitch_classes, level, span, major2, semitone, max_run, run_count, point))

    print("-" * 60)
    for names, pitch_classes, level, span, major2, semitone, max_run, run_count, _ in chords:
        print(format_result(names, pitch_classes, level, span, major2, semitone, max_run, run_count))
        print()

    a, b = chords
    point_a, point_b = a[-1], b[-1]
    if point_a is None or point_b is None:
        print("  动态张力：无法计算（有和弦的等级映射不出半径）")
        print("  动态温度：无法计算（有和弦的等级映射不出半径）")
        print("  温度差：无法计算（有和弦的等级映射不出半径）")
        print("  张力差：无法计算（有和弦的等级映射不出半径）")
        return

    direction_a, tie_a = chord_direction(a[1], NAME_TO_PITCH[a[0][0]])
    direction_b, tie_b = chord_direction(b[1], NAME_TO_PITCH[b[0][0]])
    print(f"  动态张力：{dynamic_tension(point_a, point_b):.3f}")
    temp, label = dynamic_temperature(point_a, point_b, direction_a, direction_b, tie_a, tie_b)
    print(f"  动态温度：{temp:+.3f}  ({label})")
    static_a = get_temperature(a[1], a[2], NAME_TO_PITCH[a[0][0]])[0]
    static_b = get_temperature(b[1], b[2], NAME_TO_PITCH[b[0][0]])[0]
    print(f"  温度差：{static_b - static_a:+.3f}")
    print(f"  张力差：{static_tension(b[2]) - static_tension(a[2]):+.3f}")
    print(f"  和弦点方向：{' '.join(a[0])} {math.degrees(point_a[2]) % 360:.1f}° → "
          f"{' '.join(b[0])} {math.degrees(point_b[2]) % 360:.1f}°（圆半径 10）")


# ========== 批量查询 ==========
def query_batch():
    print("进入批量模式：每行一个和弦，输入 END 结束。")
    lines = []
    while True:
        line = input(">> ").strip()
        if line.upper() == "END" or line == "":
            if line == "" and not lines:
                continue
            break
        lines.append(line)

    print("\n" + "=" * 60)
    print("批量查询结果")
    print("=" * 60)
    for line in lines:
        if "/" in line or "／" in line:
            print(f"\n输入：{line}")
            query_progression(line)
            continue
        pitch_classes, names, errors = parse_input(line)
        if errors:
            print(f"\n输入：{line}")
            print(f"  警告：无法识别的音名 {errors}")
            continue
        if len(pitch_classes) < 2:
            print(f"\n输入：{line}")
            print("  至少需要两个不同的音。")
            continue
        level, span, (major2, semitone), (max_run, run_count) = get_tension_level(pitch_classes)
        print(f"\n输入：{line}")
        print(format_result(names, pitch_classes, level, span, major2, semitone, max_run, run_count))


# ========== 温度等级（11 档） ==========
TEMP_GRADES = ["巨冷", "大冷", "中冷", "小冷", "微冷", "平衡（中性）",
               "微暖", "小暖", "中暖", "大暖", "巨暖"]
TEMP_GRADE_STEP = 2.0

GRADE_ALIASES = {g: g for g in TEMP_GRADES}
GRADE_ALIASES.update({
    "平衡(中性)": "平衡（中性）",
    "平衡": "平衡（中性）",
    "中性": "平衡（中性）",
})


def temp_grade(value):
    """温度值 → 11 档等级名。每档 2 度：0~±2 微，±2~±4 小，±4~±6 中，±6~±8 大，±8~±10 巨。"""
    if value is None:
        return None
    if value == 0:
        return "平衡（中性）"
    k = min(math.ceil(abs(value) / TEMP_GRADE_STEP - 1e-12), 5)
    return TEMP_GRADES[5 + k] if value > 0 else TEMP_GRADES[5 - k]


def resolve_grade(text):
    """输入文本 → 等级名；不是等级名时返回 None。"""
    return GRADE_ALIASES.get(text.strip().replace(" ", ""))


def grade_display(value, label):
    """结果里的档位显示：零档显示“平衡/中性”原标签，其余显示档名。"""
    g = temp_grade(value)
    return label if g == "平衡（中性）" else g


