def _static_rows():
    """全部 2~12 音组合（每音轮流当低音）的静态温度表，查一次后缓存。"""
    global _STATIC_ROWS
    if _STATIC_ROWS is None:
        rows = []
        for size in range(2, 13):
            for s in itertools.combinations(range(12), size):
                S = set(s)
                level = get_tension_level(S)[0]
                for bass in s:
                    value, label = get_temperature(S, level, bass)
                    if value is not None:
                        rows.append((S, bass, level, value, label))
        _STATIC_ROWS = rows
    return _STATIC_ROWS


def search_static(grade, mode, con=None):
    """静态温度查找。mode："one" 随机一个；"all" 全部输出。
    con 非空 = 含音/音数约束（结果和弦自身必须满足）。"""
    rows = [r for r in _static_rows() if temp_grade(r[3]) == grade]
    if con is not None:
        rows = [r for r in rows if constraint_matches(r[0], con)]
    tag = "" if con is None else _con_tag(con, False)
    if not rows:
        print(f"  静态温度里没有“{grade}”档{tag}的和弦。")
        return
    if mode == "all":
        print(f"  静态温度“{grade}”{tag}：共 {len(rows)} 个（每行第一个音是低音）")
        for S, bass, level, value, label in rows:
            print(f"    {chord_label(S, bass)}  {value:+.3f} {grade_display(value, label)}  [{level}]  张力 {static_tension(level):.3f}")
    else:
        S, bass, level, value, label = random.choice(rows)
        print(f"  静态温度“{grade}”{tag}：共 {len(rows)} 个，随机抽到——")
        print(f"    {chord_label(S, bass)}  {value:+.3f} {grade_display(value, label)}  [{level}]  张力 {static_tension(level):.3f}")


def _dyn_data():
    """动态查找用的组合表，查一次后缓存。
    组合 = (音集, 低音, 等级, 点, 方向, X, 对径音)，等级映射不出半径的组合跳过；
    分三类：对径音（tie，方向无从定号）、圆心（半径 0，乘积恒 0）、外圈。
    dir_hist 是外圈按 X → {等级: [组合号]} 的归类。"""
    global _DYN_DATA
    if _DYN_DATA is not None:
        return _DYN_DATA
    combos = []
    tie_ids = []
    center_ids = []
    outer_ids = []
    dir_hist = {}
    for size in range(2, 13):
        for s in itertools.combinations(range(12), size):
            S = set(s)
            level = get_tension_level(S)[0]
            for bass in s:
                point = chord_point(S, level, bass)
                if point is None:
                    continue
                direction, tie = chord_direction(S, bass)
                cid = len(combos)
                x = int(direction * _DIR_SCALE) % _DIR_MOD
                combos.append((S, bass, level, point, direction, x, tie))
                if tie:
                    tie_ids.append(cid)
                    continue
                if round(math.hypot(point[0], point[1]), 9) == 0:
                    center_ids.append(cid)
                else:
                    outer_ids.append(cid)
                    dir_hist.setdefault(x, {}).setdefault(level, []).append(cid)
    _DYN_DATA = (combos, tie_ids, center_ids, outer_ids, dir_hist)
    return _DYN_DATA


def _dyn_pair_value(cid_a, cid_b):
    """组合号 → 一对具体和弦的动态温度值，走真函数、与展示同一条浮点路径。"""
    combos = _dyn_data()[0]
    a = combos[cid_a]
    b = combos[cid_b]
    return dynamic_temperature(a[3], b[3], a[4], b[4], a[6], b[6])[0]


def format_dyn_pair(cid_a, cid_b):
    """一行展示一对和弦：动态温度、动态张力，外加静态温度差/静态张力差
    （和弦2 − 和弦1，与和声进行那套显示同一口径）。"""
    combos = _dyn_data()[0]
    a = combos[cid_a]
    b = combos[cid_b]
    value, label = dynamic_temperature(a[3], b[3], a[4], b[4], a[6], b[6])
    temp_diff = get_temperature(b[0], b[2], b[1])[0] - get_temperature(a[0], a[2], a[1])[0]
    tension_diff = static_tension(b[2]) - static_tension(a[2])
    return (f"{chord_label(a[0], a[1])} → {chord_label(b[0], b[1])}  {value:+.3f} {grade_display(value, label)}"
            f"  动态张力 {dynamic_tension(a[3], b[3]):.3f}  温度差 {temp_diff:+.3f}  张力差 {tension_diff:+.3f}")


def search_dynamic(grade, mode, con=None):
    """动态温度查找。mode："one" 随机一个；"all" 总数 + 20 条随机示例。
    总数取自常数表（见上）；示例用拒绝抽样——均匀随机抽一对，档位对上就留，
    留下的就是该档全部有序对上的均匀随机样本。
    con 非空 = 含音/音数约束（作用于和弦2），改走现场成对筛算（计数精确）。"""
    if con is not None:
        _search_dynamic_con(grade, mode, con)
        return
    combos = _dyn_data()[0]
    total = _DYN_GRADE_TOTALS.get(grade, 0)
    if not total:
        print(f"  动态温度里没有“{grade}”档的和弦对。")
        return
    k = 1 if mode == "one" else DYN_SAMPLE_COUNT
    tries_cap = min(int(30 * k * len(combos) ** 2 / total) + 5000, 5000000)
    samples = []
    tries = 0
    while len(samples) < k and tries < tries_cap:
        tries += 1
        cid_a = random.randrange(len(combos))
        cid_b = random.randrange(len(combos))
        if temp_grade(_dyn_pair_value(cid_a, cid_b)) == grade:
            samples.append((cid_a, cid_b))
    if mode == "all":
        print(f"  动态温度“{grade}”：共 {total} 对（全部 2~12 音的和弦两两有序对）")
        print(f"  随机 {len(samples)} 条示例（每个和弦的第一个音是低音）：")
    else:
        print(f"  动态温度“{grade}”：共 {total} 对，随机抽到——")
    for cid_a, cid_b in samples:
        print(f"    {format_dyn_pair(cid_a, cid_b)}")


def _prompt_constraint(con_text=""):
    """CLI 里问一行含音/音数约束（或直接用已给的文本）→ (con, 可继续?)。"""
    if not con_text:
        con_text = input("  输入含音/音数约束（回车跳过，如 含 C E 4音）：").strip()
    if not con_text:
        return None, True
    con, err = parse_constraint_arg(con_text)
    if err:
        print(err)
        return None, False
    return con, True


def query_grade_search(text, con=None):
    grade = resolve_grade(text)
    print(f"\n温度等级查找：{grade}")
    kind = input("  查哪种温度？（1 静态 / 2 动态 / 3 两个都查）：").strip()
    if kind in ("1", "静态", "静"):
        kinds = ["静态"]
    elif kind in ("2", "动态", "动"):
        kinds = ["动态"]
    elif kind in ("3", "都", "两个", "都要"):
        kinds = ["静态", "动态"]
    else:
        print("  已取消。")
        return
    if con is None:
        con, ok = _prompt_constraint()
        if not ok:
            return
    mode = input("  随机一个还是全部输出？（1 随机一个 / 2 全部输出）：").strip()
    if mode not in ("1", "2", "随机", "全部"):
        print("  已取消。")
        return
    print("-" * 60)
    if "静态" in kinds:
        search_static(grade, "one" if mode == "1" else "all", con)
    if "动态" in kinds:
        search_dynamic(grade, "one" if mode == "1" else "all", con)


# ========== 温度/张力查询（和弦 ↔ 属性） ==========
_GRADE_INDEX = {g: i for i, g in enumerate(TEMP_GRADES)}


def _tension_band_index(t):
    """动态张力 → 2 度带号 0~9（0-2、2-4、…、18-20）。
    边界沿用温度档惯例：正好落在带界上的值记低带（2.0 归 0-2）。"""
    k = math.ceil(t / 2 - 1e-12) - 1
    return min(max(k, 0), 9)


def _band_label(k2):
    return f"{2 * k2}-{2 * k2 + 2}"


_DIFF_STATIC = None


def _diff_t_band(v):
    """静态温度差 → 2 度档号 0~19（-20~-18、-18~-16、…、18~20）。
    边界口径同温度档：正好落在档界上的值记低档（-18.0 归 -20~-18，0 归 -2~0）。"""
    return min(max(math.ceil((v + 20) * 0.5 - 1e-12) - 1, 0), 19)


def _diff_x_band(v):
    """静态张力差 → 2 度档号 0~9（-10~-8、…、8~10），边界口径同上。"""
    return min(max(math.ceil((v + 10) * 0.5 - 1e-12) - 1, 0), 9)


def _diff_band_label(k, hi):
    """差值档号（0 基）→ 区间文字；hi = 温度差 20 / 张力差 10。"""
    lo = 2 * k - hi
    return f"{lo}~{lo + 2}"


def _decode_cell(s):
    """预存示例串 "a,b;c,d" → [(a, b), …]。"""
    return [tuple(int(v) for v in p.split(",")) for p in s.split(";")]


def _level_sort_key(lv):
    return (int(lv[:-1]), lv[-1])


def _temp_grades_in_range(a, b):
    """温度区间 (a, b] 覆盖到的档：冷侧、平衡、暖侧依次列。"""
    colds = [TEMP_GRADES[5 - k] for k in range(1, 6) if -2 * k < b and -2 * k + 2 > a]
    warms = [TEMP_GRADES[5 + k] for k in range(1, 6) if 2 * (k - 1) < b and 2 * k > a]
    return colds + (["平衡（中性）"] if a < 0 <= b else []) + warms


_RANGE_RE = re.compile(r"(-?\d+(?:\.\d+)?)\s*(?:~|～|到|—|-)\s*(-?\d+(?:\.\d+)?)")


def parse_temperature_cond(text):
    """温度条件 → (档名集合, 说明) 或 None。
    支持：档名（巨暖）；单个数（7 → 大暖、-7 → 大冷、0 → 平衡（中性））；
    区间（6-8、-8~-6、6到8），按 (a, b] 含值口径取档。"""
    grade = resolve_grade(text)
    if grade:
        return {grade}, grade
    m = _RANGE_RE.fullmatch(text.strip())
    if m:
        a, b = float(m.group(1)), float(m.group(2))
        names = _temp_grades_in_range(a, b)
        if names:
            return set(names), f"{a:g}~{b:g} → {'、'.join(names)}"
        return None
    try:
        v = float(text)
    except ValueError:
        return None
    if not math.isfinite(v):
        return None
    return {temp_grade(v)}, f"{v:g} → {temp_grade(v)}"


def parse_static_tension_cond(text):
    """静态张力条件 → (等级集合, 说明) 或 None。
    支持：全等级名（5a、10d）；大等级组号（7 → 组7 的 7a、7b）；
    带小数的张力值按"最接近的等级"（0.645 → 1b）；
    区间：整数按组（4-6 → 组4~组6），带小数按张力值（0.5-2 → 该段张力值的等级）。"""
    t = text.strip()
    m = re.fullmatch(r"(\d{1,2})\s*([a-dA-D])", t)
    if m:
        lv = f"{int(m.group(1))}{m.group(2).lower()}"
        return ({lv}, lv) if lv in LEVEL_ORDER else None
    m = _RANGE_RE.fullmatch(t)
    if m:
        a, b = float(m.group(1)), float(m.group(2))
        if re.fullmatch(r"\d+", m.group(1)) and re.fullmatch(r"\d+", m.group(2)):
            ka, kb = max(int(a), 1), int(b)
            lvs = [lv for lv in LEVEL_ORDER if ka <= int(lv[:-1]) <= kb]
            if not lvs:
                return None
            return set(lvs), f"组 {ka}~组 {kb}（{'、'.join(sorted(lvs, key=_level_sort_key))}）"
        lvs = [lv for lv in LEVEL_ORDER if a < static_tension(lv) <= b]
        if not lvs:
            return None
        return set(lvs), f"张力 {a:g}~{b:g}（{'、'.join(sorted(lvs, key=_level_sort_key))}）"
    try:
        v = float(t)
    except ValueError:
        return None
    if not math.isfinite(v):
        return None
    if "." not in t and 1 <= v <= 10 and v == int(v):
        ka = int(v)
        lvs = [lv for lv in LEVEL_ORDER if int(lv[:-1]) == ka]
        return set(lvs), f"组 {ka}（{'、'.join(sorted(lvs, key=_level_sort_key))}）"
    best = min(LEVEL_ORDER, key=lambda lv: abs(static_tension(lv) - v))
    return {best}, f"{v:g} → {best}（张力 {static_tension(best):.3f}）"


def parse_dynamic_tension_cond(text):
    """动态张力条件 → (张力带号集合, 说明) 或 None。
    单个数按它所在的 2 度带（7.5 → 6-8）；区间 a-b 从 a 所在带的上一带排到
    b 所在带（6-12 → 6-8、8-10、10-12），与计数表同一套含值口径。"""
    t = text.strip()
    m = re.fullmatch(r"(\d+(?:\.\d+)?)\s*(?:~|～|到|—|-)\s*(\d+(?:\.\d+)?)", t)
    if m:
        a, b = float(m.group(1)), float(m.group(2))
        if not (0 <= a <= b <= 20):
            return None
        lo = min(int(a // 2), 9)
        hi = _tension_band_index(b)
        if lo > hi:
            return None
        return (set(range(lo, hi + 1)),
                f"{a:g}~{b:g}（带 {'、'.join(_band_label(k) for k in range(lo, hi + 1))}）")
    try:
        v = float(t)
    except ValueError:
        return None
    if not math.isfinite(v) or v < 0 or v > 20:
        return None
    k = _tension_band_index(v)
    return {k}, f"{v:g} → 带 {_band_label(k)}"


def parse_diff_band_cond(text, hi):
    """差值档条件 → (0 基档号集合, 说明) 或 None。hi = 最大档号（温度差 20、张力差 10）。
    支持：档号 1~hi（如 10）；区间按档号闭区间（3-5、3~5），与计数表同一套档界口径。"""
    t = text.strip()
    m = re.fullmatch(r"(\d{1,2})\s*(?:~|～|到|—|-)\s*(\d{1,2})", t)
    if m:
        a, b = int(m.group(1)), int(m.group(2))
        if not (1 <= a <= b <= hi):
            return None
        lo = 2 * (a - 1) - hi
        hi_v = 2 * (b - 1) - hi + 2
        return set(range(a - 1, b)), f"档 {a}~{b}（{lo}~{hi_v}）"
    if re.fullmatch(r"\d{1,2}", t):
        k = int(t)
        if not (1 <= k <= hi):
            return None
        return {k - 1}, f"档 {k}（{_diff_band_label(k - 1, hi)}）"
    return None


def _dyn_attr_count(gi_set, k2_set):
    """动态条件命中对数：从 _DYN_JOINT_TOTALS 求子矩阵和（None = 不限）。"""
    gis = range(11) if gi_set is None else gi_set
    k2s = range(10) if k2_set is None else k2_set
    return sum(_DYN_JOINT_TOTALS[gi][k2] for gi in gis for k2 in k2s)


def search_dynamic_attr(gi_set, k2_set, desc, mode, con=None):
    """动态属性查对（属性 → 和弦对）。
    gi_set / k2_set：等级号集合 / 张力带号集合，None = 不限。
    小格子（对数 < 3 万）直接取 _DYN_SMALL_CELL_SAMPLES 预存示例，即时给
    1 或 20 条；其余用拒绝抽样（与温度等级查找同一套上限公式）。
    mode："one" 随机一个；"all" 共几对 + 20 条随机示例。
    con 非空 = 含音/音数约束（作用于和弦2），改走现场成对筛算（计数精确）。"""
    if con is not None:
        _search_dynamic_attr_con(gi_set, k2_set, desc, mode, con)
        return
    combos = _dyn_data()[0]
    count = _dyn_attr_count(gi_set, k2_set)
    if not count:
        print(f"  没有这种组合：动态属性“{desc}”命中 0 对。")
        return
    k = 1 if mode == "one" else DYN_SAMPLE_COUNT
    pool = None
    if gi_set is not None and k2_set is not None:
        pool = []
        for gi in gi_set:
            for k2 in k2_set:
                if _DYN_JOINT_TOTALS[gi][k2] == 0:
                    continue
                s = _DYN_SMALL_CELL_SAMPLES.get((TEMP_GRADES[gi], k2))
                if s is None:
                    pool = None
                    break
                pool.extend(_decode_cell(s))
            if pool is None:
                break
    if pool:
        samples = random.sample(pool, min(k, len(pool)))
    else:
        samples = []
        tries = 0
        tries_cap = min(int(30 * k * len(combos) ** 2 / count) + 5000, 5000000)
        while len(samples) < k and tries < tries_cap:
            tries += 1
            cid_a = random.randrange(len(combos))
            cid_b = random.randrange(len(combos))
            a = combos[cid_a]
            b = combos[cid_b]
            value = dynamic_temperature(a[3], b[3], a[4], b[4], a[6], b[6])[0]
            if gi_set is not None and _GRADE_INDEX[temp_grade(value)] not in gi_set:
                continue
            if k2_set is not None and _tension_band_index(dynamic_tension(a[3], b[3])) not in k2_set:
                continue
            samples.append((cid_a, cid_b))
    if mode == "all":
        print(f"  动态属性“{desc}”：共 {count} 对（全部 2~12 音的和弦两两有序对）")
        print(f"  随机 {len(samples)} 条示例（每个和弦的第一个音是低音）：")
    else:
        print(f"  动态属性“{desc}”：共 {count} 对，随机抽到——")
    for cid_a, cid_b in samples:
        print(f"    {format_dyn_pair(cid_a, cid_b)}")


def _diff_attr_count(kt_set, kx_set):
    """差值条件命中对数：从 _DIFF_JOINT_TOTALS 求子矩阵和（None = 不限）。"""
    kts = range(20) if kt_set is None else kt_set
    kxs = range(10) if kx_set is None else kx_set
    return sum(_DIFF_JOINT_TOTALS[kt][kx] for kt in kts for kx in kxs)


def _diff_static_values():
    """每个组合的（静态温度, 静态张力），首次用时算好缓存，差值抽样用。"""
    global _DIFF_STATIC
    if _DIFF_STATIC is None:
        _DIFF_STATIC = [(get_temperature(c[0], c[2], c[1])[0], static_tension(c[2]))
                        for c in _dyn_data()[0]]
    return _DIFF_STATIC


def search_diff_attr(kt_set, kx_set, desc, mode, con=None):
    """差值查对（温度差/张力差条件 → 和弦对）。
    kt_set / kx_set：温度差档号 0~19 / 张力差档号 0~9 的集合，None = 不限。
    命中数小于 3 万时走 _DIFF_SMALL_CELL_SAMPLES 预存示例（此时选中的非空格子
    必是小格、都预存过）；其余用拒绝抽样，逐对只查缓存值。
    con 非空 = 含音/音数约束（作用于和弦2），改走现场成对筛算（计数精确）。"""
    if con is not None:
        _search_diff_attr_con(kt_set, kx_set, desc, mode, con)
        return
    combos = _dyn_data()[0]
    count = _diff_attr_count(kt_set, kx_set)
    if not count:
        print(f"  没有这种组合：差值“{desc}”命中 0 对。")
        return
    k = 1 if mode == "one" else DYN_SAMPLE_COUNT
    pool = None
    if count < 30000:
        pool = []
        for kt in (range(20) if kt_set is None else kt_set):
            for kx in (range(10) if kx_set is None else kx_set):
                if _DIFF_JOINT_TOTALS[kt][kx] == 0:
                    continue
                pool.extend(_decode_cell(_DIFF_SMALL_CELL_SAMPLES[(kt, kx)]))
    if pool:
        samples = random.sample(pool, min(k, len(pool)))
    else:
        stats = _diff_static_values()
        samples = []
        tries = 0
        tries_cap = min(int(30 * k * len(combos) ** 2 / count) + 5000, 5000000)
        while len(samples) < k and tries < tries_cap:
            tries += 1
            cid_a = random.randrange(len(combos))
            cid_b = random.randrange(len(combos))
            if kt_set is not None and _diff_t_band(stats[cid_b][0] - stats[cid_a][0]) not in kt_set:
                continue
            if kx_set is not None and _diff_x_band(stats[cid_b][1] - stats[cid_a][1]) not in kx_set:
                continue
            samples.append((cid_a, cid_b))
    if mode == "all":
        print(f"  差值“{desc}”：共 {count} 对（全部 2~12 音的和弦两两有序对）")
        print(f"  随机 {len(samples)} 条示例（每个和弦的第一个音是低音）：")
    else:
        print(f"  差值“{desc}”：共 {count} 对，随机抽到——")
    for cid_a, cid_b in samples:
        print(f"    {format_dyn_pair(cid_a, cid_b)}")


_PAIR4_TOTALS = None


def _pair4_totals():
    """四维联合计数表 {(gi, k2, kt, kx): 对数}（只含非零格），首次用时解码缓存。"""
    global _PAIR4_TOTALS
    if _PAIR4_TOTALS is None:
        table = {}
        for (gi, k2), s in _PAIR4_ROWS.items():
            for rec in s.split(";"):
                k, c = rec.split(":")
                k = int(k)
                table[(gi, k2, k // 10, k % 10)] = int(c)
        _PAIR4_TOTALS = table
    return _PAIR4_TOTALS


def _pair4_samples(key):
    """预存示例池（base64 打包的 uint16 大端对）→ [(cid_a, cid_b), …]。"""
    raw = base64.b64decode(_PAIR4_SMALL_SAMPLES[key])
    return [(int.from_bytes(raw[i:i + 2], "big"), int.from_bytes(raw[i + 2:i + 4], "big"))
            for i in range(0, len(raw), 4)]


def _pair4_count(gi_set, k2_set, kt_set, kx_set):
    """四条件命中对数：从 _PAIR4_TOTALS 过滤求和（None = 不限）。"""
    return sum(c for (gi, k2, kt, kx), c in _pair4_totals().items()
               if (gi_set is None or gi in gi_set) and (k2_set is None or k2 in k2_set)
               and (kt_set is None or kt in kt_set) and (kx_set is None or kx in kx_set))


def search_pair4_attr(gi_set, k2_set, kt_set, kx_set, desc, mode, con=None):
    """合并查对（动态温度/张力档 × 温度差/张力差档，四组条件同时生效）。
    gi_set / k2_set：等级号 / 张力带号集合；kt_set / kx_set：温度差 / 张力差档
    号集合；None = 不限（调用方保证至少一侧有限定）。
    命中数 < 300 时走 _PAIR4_SMALL_SAMPLES 预存示例（此时范围内每个非空格都
    预存过，不会缺）；其余用两级拒绝抽样：先按缓存静态值筛静态差（便宜），再算
    动态温度/张力（贵），逐对只算一次，上界公式与既有查询同一套。
    con 非空 = 含音/音数约束（作用于和弦2），改走现场成对筛算（计数精确）。"""
    if con is not None:
        _search_pair4_attr_con(gi_set, k2_set, kt_set, kx_set, desc, mode, con)
        return
    combos = _dyn_data()[0]
    count = _pair4_count(gi_set, k2_set, kt_set, kx_set)
    if not count:
        print(f"  没有这种组合：动态+差值“{desc}”命中 0 对。")
        return
    k = 1 if mode == "one" else DYN_SAMPLE_COUNT
    pool = None
    if count < 300:
        pool = []
        for (gi, k2, kt, kx) in _pair4_totals():
            if (gi_set is None or gi in gi_set) and (k2_set is None or k2 in k2_set) \
                    and (kt_set is None or kt in kt_set) and (kx_set is None or kx in kx_set):
                pool.extend(_pair4_samples((gi, k2, kt, kx)))
    if pool:
        samples = random.sample(pool, min(k, len(pool)))
    else:
        stats = _diff_static_values()
        samples = []
        tries = 0
        tries_cap = min(int(30 * k * len(combos) ** 2 / count) + 5000, 5000000)
        while len(samples) < k and tries < tries_cap:
            tries += 1
            cid_a = random.randrange(len(combos))
            cid_b = random.randrange(len(combos))
            if kt_set is not None and _diff_t_band(stats[cid_b][0] - stats[cid_a][0]) not in kt_set:
                continue
            if kx_set is not None and _diff_x_band(stats[cid_b][1] - stats[cid_a][1]) not in kx_set:
                continue
            a = combos[cid_a]
            b = combos[cid_b]
            value = dynamic_temperature(a[3], b[3], a[4], b[4], a[6], b[6])[0]
            if gi_set is not None and _GRADE_INDEX[temp_grade(value)] not in gi_set:
                continue
            if k2_set is not None and _tension_band_index(dynamic_tension(a[3], b[3])) not in k2_set:
                continue
            samples.append((cid_a, cid_b))
    if mode == "all":
        print(f"  动态+差值“{desc}”：共 {count} 对（全部 2~12 音的和弦两两有序对）")
        print(f"  随机 {len(samples)} 条示例（每个和弦的第一个音是低音）：")
    else:
        print(f"  动态+差值“{desc}”：共 {count} 对，随机抽到——")
    for cid_a, cid_b in samples:
        print(f"    {format_dyn_pair(cid_a, cid_b)}")


def search_static_attr(grade_set, level_set, desc, mode, con=None):
    """静态属性查和弦（属性 → 和弦）。
    grade_set：温度档集合；level_set：等级集合；None = 不限。mode 同静态查找。
    con 非空 = 含音/音数约束（结果和弦自身必须满足）。"""
    rows = [r for r in _static_rows()
            if (grade_set is None or temp_grade(r[3]) in grade_set)
            and (level_set is None or r[2] in level_set)]
    if con is not None:
        rows = [r for r in rows if constraint_matches(r[0], con)]
    if con is None:
        head, tag = f"静态属性“{desc}”", ""
    elif desc:
        head, tag = f"静态属性“{desc}”", _con_tag(con, False)
    else:
        head, tag = f"含音/音数约束“{constraint_desc(con)}”", ""
    if not rows:
        print(f"  没有符合条件的和弦：{head}{tag}命中 0 个。")
        return
    if mode == "all":
        print(f"  {head}{tag}：共 {len(rows)} 个（每行第一个音是低音）")
        for S, bass, level, value, label in rows:
            print(f"    {chord_label(S, bass)}  {value:+.3f} {grade_display(value, label)}  [{level}]  张力 {static_tension(level):.3f}")
    else:
        S, bass, level, value, label = random.choice(rows)
        print(f"  {head}{tag}：共 {len(rows)} 个，随机抽到——")
        print(f"    {chord_label(S, bass)}  {value:+.3f} {grade_display(value, label)}  [{level}]  张力 {static_tension(level):.3f}")


# ========== 生成下一个和弦（2026-09-18 新增） ==========
_COMBO_INDEX = None


def _combo_id(S, bass):
    """(音集, 低音) → 动态组合号；不在组合表里（等级映射不出半径）返回 None。"""
    global _COMBO_INDEX
    if _COMBO_INDEX is None:
        _COMBO_INDEX = {}
        for cid, c in enumerate(_dyn_data()[0]):
            _COMBO_INDEX[(frozenset(c[0]), c[1])] = cid
    return _COMBO_INDEX.get((frozenset(S), bass))


def format_gen_pair(cid_a, cid_b):
    """生成结果一行：动态四项（同 format_dyn_pair）+ 和弦2 自身的静态温度/张力。"""
    b = _dyn_data()[0][cid_b]
    vt, vx = _diff_static_values()[cid_b]
    return (format_dyn_pair(cid_a, cid_b)
            + f"  和弦2静态 {vt:+.3f} {grade_display(vt, get_temperature(b[0], b[2], b[1])[1])}"
            + f"  和弦2张力 {vx:.3f}")


def run_generate(start_text, t_text, x_text, td_text, xd_text, st_text, sx_text, mode, con=None):
    """生成下一个和弦：起点和弦 × 六行条件（下一个和弦的动态温度档 / 动态张力带 /
    温度差档 / 张力差档，以及它自身的静态温度档 / 静态张力等级）+ 含音/音数约束
    （作用于和弦2）。条件与约束至少填一个；逐候选用真函数筛算（24540 个一次扫完）。
    mode："one" 随机一个；"all" 命中数 + 最多 20 条随机示例。"""
    start_text = start_text.strip()
    if not start_text:
        print("  请先给起点和弦（如 C E G）。")
        return
    pitch_classes, names, errors = parse_input(start_text)
    if errors:
        print(f"  起点和弦里无法识别的音名：{errors}")
        return
    if len(pitch_classes) < 2:
        print("  起点和弦至少需要两个不同的音。")
        return
    bass_pc = NAME_TO_PITCH[names[0]]
    cid_a = _combo_id(pitch_classes, bass_pc)
    if cid_a is None:
        print("  起点和弦的等级映射不出半径，生成不了下一个和弦。")
        return
    gi_set = k2_set = kt_set = kx_set = g2_set = lv2_set = None
    desc_parts = []
    if t_text:
        cond = parse_temperature_cond(t_text)
        if cond is None:
            print(f"  动态温度条件“{t_text}”无法识别（可用：大暖、7、6-8、-8~-6）。")
            return
        names_t, disp = cond
        desc_parts.append(f"动态温度 {disp}")
        gi_set = {_GRADE_INDEX[g] for g in names_t}
    if x_text:
        cond = parse_dynamic_tension_cond(x_text)
        if cond is None:
            print(f"  动态张力条件“{x_text}”无法识别（可用：7.5、6-12，范围 0~20）。")
            return
        k2_set, disp = cond
        desc_parts.append(f"动态张力 {disp}")
    if td_text:
        cond = parse_diff_band_cond(td_text, 20)
        if cond is None:
            print(f"  温度差条件“{td_text}”无法识别（可输档号 1~20，区间如 3-5）。")
            return
        kt_set, disp = cond
        desc_parts.append(f"温度差 {disp}")
    if xd_text:
        cond = parse_diff_band_cond(xd_text, 10)
        if cond is None:
            print(f"  张力差条件“{xd_text}”无法识别（可输档号 1~10，区间如 3-5）。")
            return
        kx_set, disp = cond
        desc_parts.append(f"张力差 {disp}")
    if st_text:
        cond = parse_temperature_cond(st_text)
        if cond is None:
            print(f"  和弦2静态温度条件“{st_text}”无法识别（可用：大暖、7、6-8）。")
            return
        g2_set, disp = cond
        desc_parts.append(f"和弦2静态温度 {disp}")
    if sx_text:
        cond = parse_static_tension_cond(sx_text)
        if cond is None:
            print(f"  和弦2静态张力条件“{sx_text}”无法识别（可用：5a、7、0.645、4-6）。")
            return
        lv2_set, disp = cond
        desc_parts.append(f"和弦2静态张力 {disp}")
    # 全覆盖 = 没限定（如温度差输 1-20）
    if gi_set is not None and len(gi_set) == 11:
        gi_set = None
    if k2_set is not None and len(k2_set) == 10:
        k2_set = None
    if kt_set is not None and len(kt_set) == 20:
        kt_set = None
    if kx_set is not None and len(kx_set) == 10:
        kx_set = None
    if not (gi_set or k2_set or kt_set or kx_set or g2_set or lv2_set or con is not None):
        print("  六行条件和含音/音数约束至少要填一个。")
        return
    if con is not None:
        desc_parts.append(constraint_desc(con))
    combos = _dyn_data()[0]
    a = combos[cid_a]
    stats = _diff_static_values()
    va_t, va_x = stats[cid_a]
    matches = []
    for cid_b, b in enumerate(combos):
        if con is not None and not constraint_matches(b[0], con):
            continue
        if lv2_set is not None and b[2] not in lv2_set:
            continue
        vt_b, vx_b = stats[cid_b]
        if g2_set is not None and temp_grade(vt_b) not in g2_set:
            continue
        if kt_set is not None and _diff_t_band(vt_b - va_t) not in kt_set:
            continue
        if kx_set is not None and _diff_x_band(vx_b - va_x) not in kx_set:
            continue
        if k2_set is not None and _tension_band_index(dynamic_tension(a[3], b[3])) not in k2_set:
            continue
        if gi_set is not None:
            value = dynamic_temperature(a[3], b[3], a[4], b[4], a[6], b[6])[0]
            if _GRADE_INDEX[temp_grade(value)] not in gi_set:
                continue
        matches.append(cid_b)
    print("-" * 60)
    print(f"  生成下一个和弦：{chord_label(pitch_classes, bass_pc)} → ?")
    print(f"  条件：{' × '.join(desc_parts)}")
    if not matches:
        print("  没有符合条件的下一个和弦。")
        return
    k = 1 if mode == "one" else DYN_SAMPLE_COUNT
    samples = random.sample(matches, min(k, len(matches)))
    if mode == "all":
        print(f"  共 {len(matches)} 个（每个和弦的第一个音是低音；随机 {len(samples)} 条示例）：")
    else:
        print(f"  共 {len(matches)} 个，随机抽到——")
    for cid_b in samples:
        print(f"    {format_gen_pair(cid_a, cid_b)}")


def query_generate(start_text="", con=None):
    """生成下一个和弦（CLI）：起点和弦 → 六行条件 → 约束 → 随机一个/全部。"""
    print("\n生成下一个和弦：")
    if not start_text:
        start_text = input("  请输入起点和弦（如 C E G）：").strip()
    if not start_text:
        print("  已取消。")
        return
    t_text = input("  下一个和弦的动态温度条件（回车跳过，如 大暖）：").strip()
    x_text = input("  下一个和弦的动态张力条件（回车跳过，如 6-12）：").strip()
    td_text = input("  温度差条件（回车跳过，档号 1~20）：").strip()
    xd_text = input("  张力差条件（回车跳过，档号 1~10）：").strip()
    st_text = input("  下一个和弦的静态温度条件（回车跳过，如 大暖）：").strip()
    sx_text = input("  下一个和弦的静态张力条件（回车跳过，如 5a、4-6）：").strip()
    if con is None:
        con, ok = _prompt_constraint()
        if not ok:
            return
    mode = input("  随机一个还是全部输出？（1 随机一个 / 2 全部输出）：").strip()
    if mode not in ("1", "2", "随机", "全部"):
        print("  已取消。")
        return
    run_generate(start_text, t_text, x_text, td_text, xd_text, st_text, sx_text,
                 "one" if mode == "1" else "all", con)


def query_attr_menu(con=None):
    """“查”入口：先选方向（和弦查属性 / 属性查和弦），再选静态/动态。"""
    print("\n温度/张力查询：")
    print("  1) 和弦查属性：输和弦看它的温度和张力（静态 1 个和弦，动态 2 个）")
    print("  2) 属性查和弦：输条件找和弦（静态：温度/张力）；动态：温度、张力、")
    print("     温度差、张力差四行，可混填、至少一个，同时生效")
    choice = input("  1 还是 2？（回车取消）：").strip()
    if choice == "1":
        if con is not None:
            print(f"  含音/音数约束（{constraint_desc(con)}）在这里用不上：")
            print("  和弦查属性看的是你给的那个和弦；约束只筛“属性查和弦”找出来的和弦。")
        query_chord_attr()
    elif choice == "2":
        query_attr_search(con)
    else:
        print("  已取消。")


def query_chord_attr():
    """和弦查属性：静态输 1 个和弦，动态输 2 个（用 / 隔开）。"""
    kind = input("  查静态还是动态？（1 静态 / 2 动态）：").strip()
    if kind in ("1", "静态", "静"):
        text = input("  请输入和弦（如 C E G）：").strip()
    elif kind in ("2", "动态", "动"):
        text = input("  请输入两个和弦（用 / 隔开，如 C E G / D F A）：").strip()
    else:
        print("  已取消。")
        return
    if not text:
        print("  已取消。")
        return
    query_single(text)


_ATTR_MIN_ONE = "  四个条件（温度/张力/温度差/张力差）至少输一个，或给一个含音/音数约束。"


def run_attr_search_cond(t_text, x_text, td_text, xd_text, mode, con=None):
    """属性查和弦（动态）的共用入口：四行条件文本 → 解析 → 分发 → 打印。
    CLI 与两个界面（Tkinter / Kivy）都走这里，保证提示与结果一字不差。
    t_text / x_text：温度（档）、动态张力（带）条件；td_text / xd_text：温度差、
    张力差档条件。至少填一个（或给 con 约束）；填错就地打印原因。只有动态侧 →
    search_dynamic_attr、只有差值侧 → search_diff_attr（这两条老路一字未动），
    两侧都有 → search_pair4_attr；con 非空 = 结果里的和弦2 必须满足的含音/音数约束。
    mode："one" / "all"，同各既有查找。"""
    t_text, x_text = t_text.strip(), x_text.strip()
    td_text, xd_text = td_text.strip(), xd_text.strip()
    if not (t_text or x_text or td_text or xd_text) and con is None:
        print(_ATTR_MIN_ONE)
        return
    gi_set = k2_set = kt_set = kx_set = None
    desc_parts = []
    if t_text:
        cond = parse_temperature_cond(t_text)
        if cond is None:
            print(f"  温度条件“{t_text}”无法识别（可用：大暖、7、6-8、-8~-6）。")
            return
        names, disp = cond
        desc_parts.append(f"温度 {disp}")
        gi_set = {_GRADE_INDEX[g] for g in names}
    if x_text:
        cond = parse_dynamic_tension_cond(x_text)
        if cond is None:
            print(f"  张力条件“{x_text}”无法识别（动态可用：7.5、6-12，范围 0~20）。")
            return
        k2_set, disp = cond
        desc_parts.append(f"张力 {disp}")
    if td_text:
        cond = parse_diff_band_cond(td_text, 20)
        if cond is None:
            print(f"  温度差条件“{td_text}”无法识别（可输档号 1~20，区间如 3-5）。")
            return
        kt_set, disp = cond
        desc_parts.append(f"温度差 {disp}")
    if xd_text:
        cond = parse_diff_band_cond(xd_text, 10)
        if cond is None:
            print(f"  张力差条件“{xd_text}”无法识别（可输档号 1~10，区间如 3-5）。")
            return
        kx_set, disp = cond
        desc_parts.append(f"张力差 {disp}")
    # 全覆盖 = 没限定（如温度差输 1-20）：并回老路，结果一字不变、少一层筛选
    if gi_set is not None and len(gi_set) == 11:
        gi_set = None
    if k2_set is not None and len(k2_set) == 10:
        k2_set = None
    if kt_set is not None and len(kt_set) == 20:
        kt_set = None
    if kx_set is not None and len(kx_set) == 10:
        kx_set = None
    desc = " × ".join(desc_parts)
    print("-" * 60)
    if kt_set is None and kx_set is None:
        search_dynamic_attr(gi_set, k2_set, desc, mode, con)
    elif gi_set is None and k2_set is None:
        search_diff_attr(kt_set, kx_set, desc, mode, con)
    else:
        search_pair4_attr(gi_set, k2_set, kt_set, kx_set, desc, mode, con)


def run_attr_search_static(t_text, x_text, mode, con=None):
    """属性查和弦（静态）的共用入口：温度/张力两行文本 → 解析 → 打印。
    CLI 与两个界面（Tkinter / Kivy）都走这里，保证提示与结果一字不差。
    至少填一个（或给 con 约束）；con 非空 = 结果和弦自身必须满足的约束。
    mode："one" / "all"，同各既有查找。"""
    t_text, x_text = t_text.strip(), x_text.strip()
    if not t_text and not x_text and con is None:
        print("  温度和张力至少输一个，或给一个含音/音数约束。")
        return
    grade_set = level_set = None
    desc_parts = []
    if t_text:
        cond = parse_temperature_cond(t_text)
        if cond is None:
            print(f"  温度条件“{t_text}”无法识别（可用：大暖、7、6-8、-8~-6）。")
            return
        grade_set, disp = cond
        desc_parts.append(f"温度 {disp}")
    if x_text:
        cond = parse_static_tension_cond(x_text)
        if cond is None:
            print(f"  张力条件“{x_text}”无法识别（可用：5a、7、0.645、4-6）。")
            return
        level_set, disp = cond
        desc_parts.append(f"张力 {disp}")
    desc = " × ".join(desc_parts)
    print("-" * 60)
    search_static_attr(grade_set, level_set, desc, mode, con)


def query_attr_search(con=None):
    """属性查和弦：先选静态/动态；动态给四个条件行（温度、张力、温度差、张力差），
    可随意混填、至少一个，同时生效；静态仍是温度/张力两行。
    约束没给（con = None）时在这里问一行，可跳过。"""
    kind = input("  查静态还是动态？（1 静态 / 2 动态）：").strip()
    if kind in ("1", "静态", "静"):
        dynamic = False
    elif kind in ("2", "动态", "动"):
        dynamic = True
    else:
        print("  已取消。")
        return
    if dynamic:
        t_text = input("  输入温度条件（回车跳过）：").strip()
        x_text = input("  输入张力条件（回车跳过）：").strip()
        td_text = input("  输入温度差条件（回车跳过，档号 1~20）：").strip()
        xd_text = input("  输入张力差条件（回车跳过，档号 1~10）：").strip()
        if con is None:
            con, ok = _prompt_constraint()
            if not ok:
                return
        if not (t_text or x_text or td_text or xd_text) and con is None:
            print(_ATTR_MIN_ONE)
            return
        mode = input("  随机一个还是全部输出？（1 随机一个 / 2 全部输出）：").strip()
        if mode not in ("1", "2", "随机", "全部"):
            print("  已取消。")
            return
        run_attr_search_cond(t_text, x_text, td_text, xd_text, "one" if mode == "1" else "all", con)
        return
    t_text = input("  输入温度条件（回车跳过）：").strip()
    x_text = input("  输入张力条件（回车跳过）：").strip()
    if con is None:
        con, ok = _prompt_constraint()
        if not ok:
            return
    mode = input("  随机一个还是全部输出？（1 随机一个 / 2 全部输出）：").strip()
    if mode not in ("1", "2", "随机", "全部"):
        print("  已取消。")
        return
    run_attr_search_static(t_text, x_text, "one" if mode == "1" else "all", con)


# ========== 主程序 ==========
def main():
    print("=" * 60)
    print("和弦张力等级查询工具")
    print("=" * 60)
    print("输入方式：")
    print("  空格或逗号分隔音名，例如：C E G 或 C, E, G")
    print("  和声进行：两个和弦用 / 隔开，例如：C E G / D F A")
    print("  降号用 j 前缀：jD = Db, jE = Eb, jA = Ab, jB = Bb")
    print("  也支持：bD, bE, Db, Eb, Ab, Bb")
    print("  升号用 #：C#, F#, G#；#B = C, #E = F")
    print("  带八度也可以：C4 E4 G4 B4（八度会被忽略）")
    print()
    print("  温度等级查找（静态温度 / 动态温度）：直接输入等级名，如 巨暖、微冷、平衡（中性）")
    print("    等级（每档 2 度）：巨冷 大冷 中冷 小冷 微冷 平衡（中性） 微暖 小暖 中暖 大暖 巨暖")
    print("    可选随机输出一个或全部输出")
    print()
    print("  温度/张力查询：输入 查 进入（先选 和弦查属性 / 属性查和弦，再选 静态 / 动态）")
    print("    温度条件：档名（大暖）、单个数（7、-7、0）、区间（6-8、-8~-6）")
    print("    静态张力=等级：5a、7（组7 全部）、0.645（就近等级）、4-6（组4~组6）")
    print("    动态张力按 2 度带（0-2、2-4 … 18-20）：7.5、6-12，范围 0~20")
    print("    属性查和弦的动态：温度、张力、温度差、张力差四行可混填（至少一个）")
    print("    差值条件按档号（每档 2 度，和弦2 减和弦1），如 10、3-5：")
    print("      温度差 20 档：档1 = -20~-18 … 档10 = -2~0、档11 = 0~2 … 档20 = 18~20")
    print("      张力差 10 档：档1 = -10~-8 … 档5 = -2~0、档6 = 0~2 … 档10 = 8~10")
    print()
    print("  含音/音数约束（跟在 等级名 / 查 / 生成 后面一起输入，界面里填在约束框）：")
    print("    含 C E（必须包含这些音）、4音、3-4音（音数 2~12）")
    print("    例：大暖 含 C 、查 含 C E 4音 、生成 C E G 含 C 6音")
    print("    成对结果（和弦1 → 和弦2）里的约束一律作用在“和弦2”（被找的下一个和弦）")
    print()
    print("  生成下一个和弦：输入 生成 起点和弦（如 生成 C E G），再逐行给六个条件：")
    print("    下一个和弦的动态温度 / 动态张力、温度差 / 张力差，以及它自身的静态")
    print("    温度 / 静态张力；可混填、至少一个，配含音/音数约束也行。")
    print()
    print("命令：")
    print("  batch   批量查询（每行一个和弦）")
    print("  查      温度/张力查询（和弦 ↔ 属性）")
    print("  生成    生成下一个和弦（起点和弦 + 条件 / 约束）")
    print("  q       退出")
    print("=" * 60)

    while True:
        text = input("\n请输入和弦音：").strip()
        if text.lower() in ("q", "quit", "exit"):
            print("再见！")
            break
        if not text:
            continue
        # 过滤 VS Code 运行命令回显
        if is_likely_command_line(text):
            continue
        # 含音 / 音数约束：先把约束语句剥出来，剩下的照旧走各入口
        rest, con, cdesc, cerr = parse_constraints(text)
        if cerr:
            print(f"  {cerr}")
            continue
        if rest.lower() == "batch":
            if con is not None:
                print("  批量查询不支持含音/音数约束（每行都是给定的和弦）。")
                continue
            query_batch()
            continue
        if rest.startswith("生成"):
            query_generate(rest[2:].strip(), con)
            continue
        if rest in ("查", "查询"):
            query_attr_menu(con)
            continue
        if not rest:
            print(f"  只写了约束（{cdesc}）：前面再加上 等级名 / 查 / 生成，")
            print("  例如：大暖 含 C 、查 4音 、生成 C E G 含 C E。")
            continue
        if resolve_grade(rest):
            query_grade_search(rest, con)
            continue
        if con is not None:
            print(f"  含音/音数约束（{cdesc}）是“找和弦”用的，跟在 等级名 / 查 / 生成 后面：")
            print("  例如：大暖 含 C 、查 含 C E 、生成 C E G 含 C 。单个和弦查属性不用约束。")
            continue
        query_single(rest)


if __name__ == "__main__":
    main()